fn reverse(s: Vec<i8>) -> Vec<i8> {
    // Consume the input vector `s`, iterate over its elements in reverse order,
    // and collect them into a new Vec<i8>.
    let rev: Vec<i8> = s.into_iter().rev().collect();
    rev
}

